-- tasks — the unit of work the whole app is built on.
--
-- Completing a task is the single moment that moves an account forward: it
-- awards xp_value, extends the streak, writes a row to the XP ledger
-- (growth.sql) and counts toward the user's goals.
--
-- user_id holds the username, which is what every store keys on.

CREATE TABLE IF NOT EXISTS tasks (
    id                  TEXT PRIMARY KEY,
    user_id             TEXT NOT NULL REFERENCES users (username) ON DELETE CASCADE,

    title               TEXT NOT NULL DEFAULT '',
    description         TEXT DEFAULT '',
    priority            TEXT DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high')),
    status              TEXT DEFAULT 'todo' CHECK (status IN ('todo', 'done', 'expired')),

    -- What completing it is worth.
    xp_value            INTEGER DEFAULT 0 CHECK (xp_value >= 0),

    -- What the task is about, as an id from the catalogue in
    -- backend/config/subjects.py. Optional: a task without one is a task
    -- nobody chose to file, not an error. Deliberately not a foreign key —
    -- the catalogue is code, not a table, so that it can be edited in one
    -- place without a migration.
    subject             TEXT,

    -- What this task is execution *for*: a goal, and the checkpoint inside it.
    -- Both optional, and most tasks have neither — work done for its own sake
    -- is not a lesser kind of work. Not foreign keys, for the same reason the
    -- calendar's references are not: a goal deleted from under a task should
    -- orphan the link, not take the task with it. The API treats a link that
    -- points at nothing as no link, which is what it is.
    goal_id             TEXT,
    milestone_id        TEXT,

    due_date            TEXT,
    show_on_calendar    BOOLEAN DEFAULT TRUE,

    -- Timer, when one was set for this task.
    timer_duration      INTEGER,
    timer_expired       BOOLEAN,

    created_at          TEXT,
    completed_at        TEXT,

    -- Recorded on completion, and read by the report card's efficiency metric:
    -- how long it took, and whether it beat its deadline. Tasks completed
    -- before this was tracked are left out of those scores.
    completion_seconds  INTEGER,
    met_deadline        BOOLEAN,

    -- What the person said about the work, one to five stars each, asked once
    -- when the task is marked done. Both nullable and both stay null when the
    -- prompt is dismissed: an unrated task is a task nobody rated, which is a
    -- different thing from one rated zero, and nothing may average the two
    -- together.
    --
    -- Deliberately two numbers rather than one. How hard a task was and how
    -- well it went are independent — an easy task done badly and a brutal one
    -- done well are the two readings a single "how did that go" would collapse
    -- into the same middling star.
    difficulty          INTEGER CHECK (difficulty BETWEEN 1 AND 5),
    execution           INTEGER CHECK (execution BETWEEN 1 AND 5),

    -- The third question, asked only when the account has turned it on
    -- (rating_depth 'reasons'): the one thing that made the difference. One of
    -- the twelve words in REASONS in backend/api/tasks.py — six for a task
    -- that went badly, six for one that went well — and which side it came
    -- from is recoverable from the word itself.
    --
    -- Deliberately not a foreign key and deliberately not free text, for the
    -- two reasons `subject` above is neither: the vocabulary is code rather
    -- than a table, and an answer that cannot be counted alongside other
    -- answers is not worth the question. Null is the ordinary state — it means
    -- the question was not asked or not answered.
    reason              TEXT,

    -- What the goal matcher concluded about this task, and which version of
    -- it did: 'matched', 'ambiguous', 'unmatched' or 'pending', and an integer
    -- that goes up when the matching rules change. Null on a task that has
    -- never been through it, which is different from 'unmatched' — that one
    -- was looked at and belongs to no goal. The goals themselves are rows of
    -- task_goal_matches (data/sql/goals.sql). No CHECK, for the reason the
    -- ratings above give; backend/goal_matcher narrows the values.
    goal_match_status   TEXT,
    goal_match_version  INTEGER
);

CREATE INDEX IF NOT EXISTS tasks_user_status_idx ON tasks (user_id, status);
CREATE INDEX IF NOT EXISTS tasks_user_completed_idx ON tasks (user_id, completed_at DESC);

-- ---- rows: tasks ----
